"""Independent original-core rerun of one stored bounded source evaluation."""
import gzip,hashlib,json,resource,sys,time
from pathlib import Path
ROOT=next(p for p in Path(__file__).resolve().parents if (p/'voxel_character/common/core.py').exists());sys.path.insert(0,str(ROOT));from voxel_character.common import core
HERE=Path(__file__).resolve().parent
start=time.monotonic();master=json.loads(gzip.decompress((HERE/'image_derived.master.json.gz').read_bytes()));old=json.loads(gzip.decompress((HERE/'slabs/000.compiled.json.gz').read_bytes()));bounds={k:old['evaluation_scope'][k] for k in ('min','max')};new=core.compile_master(master,{'pitch':.125},cell_bounds=bounds,max_candidate_cells=150000,max_output_cells=100000)
checks={'actual_cell_rows_exact':new['cells']==old['cells'],'payload_hash_exact':new['payload_hash']==old['payload_hash'],'master_hash_exact':new['master_hash']==old['master_hash'],'original_compiler_sha_exact':new['compiler_source_hash']==old['compiler_source_hash'],'candidate_count_exact':new['candidate_cells']==old['candidate_cells'],'constraint_result_exact':new['constraints']==old['constraints']};assert all(checks.values())
report={'schema':'riverstone.image_reconstruction.original_core_replay.v1','all_pass':True,'tests':checks,'core_path':str(Path(core.__file__).relative_to(ROOT)),'core_sha256':hashlib.sha256(Path(core.__file__).read_bytes()).hexdigest(),'master_sha256':hashlib.sha256((HERE/'image_derived.master.json.gz').read_bytes()).hexdigest(),'replayed_compiled_sha256':hashlib.sha256((HERE/'slabs/000.compiled.json.gz').read_bytes()).hexdigest(),'source_shapes_cropped':False,'cell_bounds':bounds,'compared_cell_count':len(old['cells']),'sampling_calls':1,'wall_seconds':time.monotonic()-start,'user_cpu_seconds':resource.getrusage(resource.RUSAGE_SELF).ru_utime,'system_cpu_seconds':resource.getrusage(resource.RUSAGE_SELF).ru_stime,'peak_rss_kib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss};p=HERE/'original_core_replay.json';assert not p.exists();p.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report),flush=True)
